package com.shopsphere.config;
import com.shopsphere.entity.*; import com.shopsphere.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(UserRepository users,CategoryRepository categories,PasswordEncoder encoder,CartRepository carts){return args->{if(users.findByEmailIgnoreCase("admin@shopsphere.local").isEmpty()){User u=new User();u.setName("Admin");u.setEmail("admin@shopsphere.local");u.setPasswordHash(encoder.encode("Admin@12345"));u.setRole(Role.ADMIN);users.save(u);Cart c=new Cart();c.setUser(u);carts.save(c);} if(categories.count()==0){Category c=new Category();c.setName("Electronics");c.setSlug("electronics");c.setDescription("Electronic devices and accessories");categories.save(c);Category c2=new Category();c2.setName("Fashion");c2.setSlug("fashion");categories.save(c2);}};}}
